CREATE TABLE catalogo_razas_bovinas (
    id              VARCHAR(36)   NOT NULL DEFAULT (UUID()),
    codigo          VARCHAR(80)   NOT NULL,
    nombre          VARCHAR(140)  NOT NULL,
    especie         VARCHAR(40)   NOT NULL DEFAULT 'BOVINA',
    aptitud         VARCHAR(40)   NOT NULL,
    tipo_genetico   VARCHAR(60)   NOT NULL,
    origen          VARCHAR(120)  NULL,
    descripcion     TEXT          NULL,
    fuente          VARCHAR(120)  NOT NULL DEFAULT 'SENASA',
    activo          BIT           NOT NULL DEFAULT b'1',
    created_at      DATETIME(6)   DEFAULT CURRENT_TIMESTAMP(6),
    updated_at      DATETIME(6)   DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    deleted_at      DATETIME(6)   NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_catalogo_razas_bovinas_codigo UNIQUE (codigo),
    CONSTRAINT uk_catalogo_razas_bovinas_nombre UNIQUE (nombre),
    INDEX idx_catalogo_razas_bovinas_nombre (nombre),
    INDEX idx_catalogo_razas_bovinas_aptitud (aptitud, activo),
    INDEX idx_catalogo_razas_bovinas_tipo (tipo_genetico, activo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

